function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 365;
  const pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  const esVenta = { confirmado: true, enviado: true, entregado: true, novedad: true };
  const conteo = {};
  for (const p of pedidos) {
    if (!p || !esVenta[p.estado]) continue;
    if (!p.creado) continue;
    const d = dia(p.creado);
    conteo[d] = (conteo[d] || 0) + 1;
  }
  const serie = [];
  let total = 0;
  for (let n = N - 1; n >= 0; n--) {
    const etiqueta = dia(new Date(Date.parse(datos.hoy) - n * 86400000).toISOString());
    const v = conteo[etiqueta] || 0;
    serie.push({ etiqueta: etiqueta, valor: v });
    total += v;
  }
  return {
    valor: total,
    unidad: "pedidos",
    serie: serie,
    nota: "Cuenta pedidos confirmados, enviados, entregados y con novedad por día de creación en Bogotá en los últimos 365 días incluyendo hoy."
  };
}

