function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 60;
  var corte = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var esVenta = function (e) { return e === 'confirmado' || e === 'enviado' || e === 'entregado' || e === 'novedad'; };
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!esVenta(p.estado)) continue;
    if (!p.creado || !p.clienteId) continue;
    if (!(dia(p.creado) > corte)) continue;
    conteo[p.clienteId] = (conteo[p.clienteId] || 0) + 1;
  }
  var compradores = 0;
  var repetidores = 0;
  for (var k in conteo) {
    if (Object.prototype.hasOwnProperty.call(conteo, k)) {
      compradores++;
      if (conteo[k] > 1) repetidores++;
    }
  }
  var valor = 0;
  if (compradores > 0) valor = Math.round((repetidores / compradores * 100) * 10) / 10;
  return { valor: valor, unidad: '%', nota: 'Porcentaje de clientes con m\u00e1s de una venta sobre los que compraron en los \u00faltimos 60 d\u00edas, contando solo confirmados, enviados, entregados y novedad.' };
}

