function consultar(datos) {
  var dia = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  };
  var fmtBogota = function (iso) {
    var s = new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString();
    return s.slice(0, 10) + " " + s.slice(11, 16);
  };
  var esVenta = function (e) {
    return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  };
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var nombres = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) nombres[c.id] = c.nombre || c.telefonoEnmascarado || c.id;
  }
  var N = 365;
  var limiteDia = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var agg = {};
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || !p.creado || !p.clienteId) continue;
    if (!esVenta(p.estado)) continue;
    var d = dia(p.creado);
    if (!(d > limiteDia)) continue;
    var k = p.clienteId;
    if (!agg[k]) agg[k] = { total: 0, n: 0, ultimo: null };
    var t = typeof p.total === "number" ? p.total : 0;
    agg[k].total += t;
    agg[k].n += 1;
    if (!agg[k].ultimo || p.creado > agg[k].ultimo) agg[k].ultimo = p.creado;
  }
  var filas = [];
  for (var id in agg) {
    if (!Object.prototype.hasOwnProperty.call(agg, id)) continue;
    var a = agg[id];
    filas.push({
      cliente: nombres[id] || id,
      total_comprado: a.total,
      numero_pedidos: a.n,
      ultimo_pedido: a.ultimo ? fmtBogota(a.ultimo) : null
    });
  }
  filas.sort(function (x, y) {
    if (y.total_comprado !== x.total_comprado) return y.total_comprado - x.total_comprado;
    if (y.numero_pedidos !== x.numero_pedidos) return y.numero_pedidos - x.numero_pedidos;
    return x.cliente < y.cliente ? -1 : 1;
  });
  return filas.slice(0, 10);
}

