function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const hoyDia = dia(datos.hoy);
  const limite = dia(new Date(Date.parse(datos.hoy) - 365 * 86400000).toISOString());
  const pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  const estados = ["pendiente", "confirmado", "enviado", "entregado", "novedad", "cancelado"];
  const conteo = { pendiente: 0, confirmado: 0, enviado: 0, entregado: 0, novedad: 0, cancelado: 0 };
  for (const p of pedidos) {
    if (!p) continue;
    if (p.creado) {
      const d = dia(p.creado);
      if (!(d > limite && d <= hoyDia)) continue;
    }
    const e = p.estado;
    if (Object.prototype.hasOwnProperty.call(conteo, e)) conteo[e] += 1;
  }
  const serie = estados.map(function (e) { return { etiqueta: e, valor: conteo[e] }; });
  let total = 0;
  for (const e of estados) total += conteo[e];
  return { valor: total, unidad: "pedidos", serie: serie, nota: "Conteo por estado en los últimos 365 días calendario hasta hoy (hora de Bogotá)." };
}

