  var pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  var productos = (datos && datos.tablas && datos.tablas.productos) || [];
  var nombresPorId = {};
  for (var i = 0; i < productos.length; i++) {
    var p = productos[i];
    if (p && p.id && p.nombre) nombresPorId[p.id] = p.nombre;
  }
  var hoyMs = Date.parse(datos.hoy);
  var limiteDia = dia(new Date(hoyMs - N * 86400000).toISOString());
  var esVenta = function (estado) {
    return estado === 'confirmado' || estado === 'enviado' || estado === 'entregado' || estado === 'novedad';
  };
  var porId = {};
  var total = 0;
  for (var k = 0; k < pedidos.length; k++) {
    var ped = pedidos[k];
    if (!ped || !esVenta(ped.estado)) continue;
    if (!ped.creado) continue;
    var d = dia(ped.creado);
    if (!(d > limiteDia)) continue;
    var items = ped.items || [];
    for (var j = 0; j < items.length; j++) {
      var it = items[j];
      if (!it) continue;
      var cant = Number(it.cantidad);
      if (!isFinite(cant) || cant <= 0) continue;
      cant = Math.floor(cant);
      var pid = it.productoId || it.productoID || it.id || it.nombre || 'sin-id';
      var nom = it.nombre || nombresPorId[pid] || String(pid);
      if (!porId[pid]) porId[pid] = { etiqueta: nom, valor: 0 };
      if (it.nombre) porId[pid].etiqueta = it.nombre;
      else if (nombresPorId[pid]) porId[pid].etiqueta = nombresPorId[pid];
      porId[pid].valor += cant;
      total += cant;
    }
  }
  var serie = Object.keys(porId).map(function (key) { return porId[key]; });
  serie.sort(function (a, b) { return b.valor - a.valor; });
  return {
    valor: total,
    unidad: 'unidades',
    serie: serie,
    nota: 'Unidades sumadas (cantidad) por producto en pedidos venta (confirmado, enviado, entregado y novedad) de los últimos 365 días.'
  };
}

