function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 30;
  var hoyDia = dia(datos.hoy);
  var limiteDia = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var porCiudad = {};
  var tot = 0;
  var canc = 0;
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p || !p.creado) continue;
    var d = dia(p.creado);
    if (!(d > limiteDia && d <= hoyDia)) continue;
    var ciudad = p.ciudad || 'Sin ciudad';
    if (!porCiudad[ciudad]) porCiudad[ciudad] = { total: 0, cancelados: 0 };
    porCiudad[ciudad].total += 1;
    tot += 1;
    if (p.estado === 'cancelado') {
      porCiudad[ciudad].cancelados += 1;
      canc += 1;
    }
  }
  function pct(c, t) {
    if (!t) return 0;
    return Math.round((c / t * 100) * 10) / 10;
  }
  var serie = Object.keys(porCiudad).sort().map(function (ciudad) {
    var g = porCiudad[ciudad];
    return { etiqueta: ciudad, valor: pct(g.cancelados, g.total) };
  });
  var valorGlobal = pct(canc, tot);
  return {
    valor: valorGlobal,
    unidad: '%',
    serie: serie,
    nota: 'Porcentaje = cancelados/total*100 por ciudad en los ultimos 30 dias (dia en Bogota); global ' + valorGlobal + '% sobre ' + tot + ' pedidos.'
  };
}

