  };
  var mesBogota = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 7);
  };
  var N = 365;
  var hoyMs = Date.parse(datos.hoy);
  var limite = dia(new Date(hoyMs - N * 86400000).toISOString());
  var mesesOrden = [];
  var visto = {};
  for (var n = N - 1; n >= 0; n--) {
    var d = dia(new Date(hoyMs - n * 86400000).toISOString());
    var m = d.slice(0, 7);
    if (!visto[m]) {
      visto[m] = true;
      mesesOrden.push(m);
